  "verses": [
    {
      "verse": 1,
      "text_ar": "في اليوم الذي مرض فيه وعلم أنه سيتعين عليه مغادرة مسكنه الجسدي، دعا بنيه السبعة وبناته الثلاث معاً وكلمهم هكذا:",
      "chapter": 1
    },
    {
      "verse": 2,
      "text_ar": "اصنعوا دائرة حول لي، يا أولادي، واسمعوا، فإني أخبركم بما صنعه الرب معي وكل ما حدث لي.",
      "chapter": 1
    },
    {
      "verse": 3,
      "text_ar": "لأني أنا أيوب أبوكم.",
      "chapter": 1
    },
    {
      "verse": 4,
      "text_ar": "فاعلموا إذن يا أولادي أنكم جيل مختار واحذروا لمولدكم النبيل.",
      "chapter": 1
    },
    {
      "verse": 5,
      "text_ar": "لأني من بني عيسو. وأخي هو ناحور، وأمكم هي دينة. بها صرتُ أباكم.",
      "chapter": 1
    }
  ],
  "book_code": "TJOB"
}
